import json
from pathlib import Path
R=Path(__file__).parent
overrides={}
def put(locale,section,text):
    overrides.setdefault(locale,{})[str(section)]=text.strip()

put('es-ES',4,"""Una intrusión oscura y plana se extiende entre estratos sedimentarios claros. Aquí el magma entró en la corteza, ocupó el espacio disponible y se enfrió hasta convertirse en roca. Cuando una intrusión sigue la estratificación, se denomina filón-capa. Si atraviesa los estratos, hablamos de un dique magmático. Sus contactos conservan rutas distintas. Imagina seguir el borde oscuro junto a la roca que lo rodea. Si todo el conjunto se abomba después, la intrusión puede curvarse con él. La erosión puede dejar una traza anular al cortar ese cuerpo curvado. Richat contiene dos grandes cuerpos de gabro con contornos curvos en superficie. El gabro es una roca ígnea de cristales gruesos, formada cuando el magma se enfría bajo tierra. Algunas interpretaciones anteriores los consideraban diques anulares vinculados a una intrusión central. Un trabajo posterior estudió otra posibilidad: filones-capa más antiguos, levantados junto con las rocas sedimentarias. Eso cambia el orden de los acontecimientos. Un estudio publicado en dos mil veinticuatro añadió análisis químicos y estudios con argón. La composición de los gabros recuerda a grupos asociados con la Provincia Magmática del Atlántico Central, una gran fase de actividad de hace unos doscientos millones de años. Los autores propusieron una intrusión inicial paralela a los estratos. Otra intrusión, más reciente, habría elevado aquellos cuerpos y las capas circundantes. El dibujo visible reuniría así episodios muy separados. La geometría enterrada sigue en discusión; esta interpretación es una propuesta contrastada con datos, no una fotografía del subsuelo. Cerca del centro aparecen fragmentos de roca cementados entre sí. ¿Qué los rompió y qué rellenó después sus huecos?""")
put('fr-FR',4,"""Une intrusion sombre, en forme de lame, s'étend entre des couches sédimentaires claires. Le magma est entré dans la croûte, a occupé l'espace disponible, puis a refroidi jusqu'à devenir une roche solide. Une intrusion parallèle à la stratification s'appelle un filon-couche. Une intrusion qui recoupe les couches est un dyke. Leurs contacts révèlent des chemins différents. Imaginez suivre la limite sombre le long des roches qui l'enveloppent. Si tout l'ensemble se bombe ensuite, le filon-couche peut se courber avec lui. L'érosion de ce corps courbé peut faire apparaître une trace annulaire. Richat possède deux grands corps de gabbro aux contours courbes en surface. Le gabbro est une roche magmatique à gros cristaux, formée par le refroidissement du magma en profondeur. Des interprétations antérieures y voyaient des filons annulaires liés à une intrusion centrale. Des travaux ultérieurs ont étudié une autre possibilité : des filons-couches plus anciens, soulevés avec les roches sédimentaires environnantes. L'ordre des événements change. Une étude publiée en deux mille vingt-quatre a ajouté des analyses chimiques et des travaux fondés sur l'argon. La composition des gabbros ressemble à celle de groupes associés à la Province magmatique de l'Atlantique central, une immense phase d'activité remontant à environ deux cents millions d'années. Les auteurs proposent une mise en place initiale parallèle aux couches. Une intrusion plus récente aurait ensuite soulevé les anciens corps et leur encaissant. Un même dessin rassemble plusieurs épisodes. La géométrie enfouie reste discutée ; cette interprétation est une proposition confrontée aux données, pas une photographie du sous-sol. Près du centre, des fragments de roche sont cimentés ensemble. Qu'est-ce qui les a brisés, puis a rempli leurs interstices ?""")
put('de-DE',4,"""Ein dunkler, flacher Gesteinskörper liegt zwischen hellen Sedimentschichten. Magma drang in die Erdkruste ein, breitete sich im verfügbaren Raum aus und erstarrte. Eine Intrusion parallel zur Schichtung heißt Lagergang. Ein Gang, der die Schichten durchschneidet, nimmt einen anderen Weg. Die Kontaktflächen bewahren diesen Unterschied. Stellen Sie sich vor, Sie verfolgen die dunkle Grenze neben dem umgebenden Gestein. Wird der ganze Schichtenstapel später aufgewölbt, kann sich der Lagergang mitbiegen. Erosion durch diesen gekrümmten Körper kann eine ringförmige Spur freilegen. Richat enthält zwei große Gabbrokörper mit gebogenen Umrissen an der Oberfläche. Gabbro ist ein grobkristallines magmatisches Gestein, das durch langsames Abkühlen von Magma im Untergrund entsteht. Ältere Deutungen betrachteten diese Körper als Ringgänge einer zentralen Intrusion. Spätere Arbeiten untersuchten eine andere Möglichkeit: ältere Lagergänge, die zusammen mit den Sedimentgesteinen angehoben wurden. Das verändert die Reihenfolge. Eine Studie aus dem Jahr zweitausendvierundzwanzig ergänzte chemische Analysen und Untersuchungen mit Argon. Die Zusammensetzung ähnelt Gesteinsgruppen der Zentralatlantischen Magmatischen Provinz, einer gewaltigen Phase magmatischer Aktivität vor ungefähr zweihundert Millionen Jahren. Nach dem Vorschlag der Autoren drang das ältere Magma zunächst parallel zu den Schichten ein. Eine jüngere Intrusion könnte diese Körper und das umgebende Gestein später zur Kuppel aufgewölbt haben. Der sichtbare Umriss vereint dann weit auseinanderliegende Ereignisse. Die genaue Geometrie im Untergrund bleibt umstritten; die Lagergang-Deutung ist ein anhand von Daten geprüfter Vorschlag, kein unterirdisches Foto. Nahe dem Zentrum sind Gesteinsbruchstücke miteinander verkittet. Was zerbrach sie, und was füllte später ihre Zwischenräume?""")
put('it-IT',4,"""Un corpo scuro e appiattito si estende fra strati sedimentari chiari. Il magma è entrato nella crosta, ha occupato lo spazio disponibile e si è raffreddato fino a diventare roccia. Un'intrusione parallela alla stratificazione è un filone-strato. Un'intrusione che taglia gli strati è un dicco. I contatti conservano questi percorsi diversi. Immagina di seguire il bordo scuro lungo le rocce che lo racchiudono. Se l'intera successione viene incurvata più tardi, il corpo magmatico può piegarsi insieme a essa. L'erosione può tagliare quel corpo curvo e lasciare una traccia ad anello. Richat contiene due importanti corpi di gabbro con contorni curvi in superficie. Il gabbro è una roccia magmatica a cristalli grossi, formata dal raffreddamento del magma nel sottosuolo. Interpretazioni precedenti consideravano quei corpi dicchi anulari collegati a un'intrusione centrale. Lavori successivi hanno esplorato un'alternativa: filoni-strato più antichi, sollevati insieme alle rocce sedimentarie circostanti. Cambia la successione degli eventi. Uno studio pubblicato nel duemilaventiquattro ha aggiunto analisi chimiche e indagini basate sull'argon. La composizione dei gabbri ricorda gruppi associati alla Provincia Magmatica dell'Atlantico Centrale, un'immensa fase di attività risalente a circa duecento milioni di anni fa. Gli autori propongono una prima intrusione parallela agli strati. Un'intrusione magmatica più recente avrebbe poi sollevato quei corpi e le rocce circostanti, formando una cupola. Un unico disegno riunirebbe episodi molto lontani. La geometria sepolta resta discussa; questa interpretazione è una proposta confrontata con i dati, non una fotografia del sottosuolo. Vicino al centro, frammenti di rocce diverse sono cementati insieme. Che cosa li ha spezzati, e che cosa ha riempito i vuoti?""")
put('pt-PT',4,"""Um corpo magmático escuro e achatado estende-se entre camadas sedimentares claras. O magma entrou na crosta, ocupou o espaço disponível e arrefeceu até se tornar rocha sólida. Uma intrusão paralela à estratificação é uma soleira magmática. Uma intrusão que corta as camadas é um dique magmático. Os contactos revelam percursos diferentes. Imagina seguir o limite escuro junto às rochas que o envolvem. Se todo o conjunto se arquear mais tarde, a soleira pode curvar-se com ele. A erosão desse corpo curvo pode deixar um traço em anel. Richat contém dois importantes corpos de gabro com contornos curvos à superfície. O gabro é uma rocha magmática de cristais grosseiros, formada pelo arrefecimento do magma no subsolo. Interpretações anteriores consideravam estes corpos diques anelares ligados a uma intrusão central. Trabalhos posteriores exploraram outra possibilidade: soleiras mais antigas, levantadas com as rochas sedimentares envolventes. Isso altera a ordem dos acontecimentos. Um estudo publicado em dois mil e vinte e quatro acrescentou análises químicas e investigações com árgon. A composição dos gabros assemelha-se a grupos associados à Província Magmática do Atlântico Central, uma enorme fase de atividade de há cerca de duzentos milhões de anos. Os autores propuseram uma instalação inicial paralela às camadas. Uma intrusão mais recente poderia depois elevar esses corpos e as rochas circundantes, formando uma cúpula. O mesmo desenho reuniria episódios muito afastados. A geometria enterrada continua em discussão; esta interpretação é uma proposta confrontada com os dados, não uma fotografia do subsolo. Perto do centro, fragmentos de rochas diferentes estão cimentados uns aos outros. O que os partiu, e o que preencheu depois os espaços?""")
put('nl-NL',4,"""Een donker, plaatvormig gesteentelichaam ligt tussen lichte sedimentlagen. Magma drong de aardkorst binnen, vulde beschikbare ruimte en stolde. Een plaatvormige intrusie evenwijdig aan de gelaagdheid heet een sill. Een magmatische gang die lagen doorsnijdt, volgt een andere route. De contactvlakken bewaren dat verschil. Stel je voor dat je de donkere grens langs het omringende gesteente volgt. Als het hele lagenpakket later omhoogbuigt, kan de intrusie meebuigen. Erosie door dat gekromde lichaam kan een ringvormig spoor blootleggen. Richat bevat twee opvallende gabbrolichamen met gebogen omtrekken aan het oppervlak. Gabbro is een grofkristallijn stollingsgesteente, gevormd doordat magma ondergronds afkoelde. Eerdere interpretaties zagen deze lichamen als ringvormige gangen rond een centrale intrusie. Later onderzoek verkende een andere mogelijkheid: oudere plaatvormige intrusies die samen met de sedimentgesteenten werden opgetild. Dat verandert de volgorde. Een studie uit tweeduizendvierentwintig voegde chemische analyses en onderzoek met argon toe. De samenstelling van de gabbro's lijkt op gesteentegroepen van de Centraal-Atlantische Magmatische Provincie, een enorme fase van magmatische activiteit rond tweehonderd miljoen jaar geleden. De auteurs stellen voor dat het oudere magma eerst evenwijdig aan de lagen binnendrong. Een jongere intrusie kon vervolgens de oudere lichamen en hun omgeving tot een koepel opheffen. Eén patroon zou zo ver uiteenliggende gebeurtenissen verenigen. De precieze vormen onder de grond blijven onderwerp van discussie; deze interpretatie is een met gegevens getoetst voorstel, geen ondergrondse foto. Bij het centrum zijn brokstukken van verschillende gesteenten aan elkaar gekit. Wat brak ze, en wat vulde later de openingen?""")
put('pl-PL',4,"""Ciemne, płaskie ciało magmowe leży pomiędzy jasnymi warstwami osadowymi. Magma wniknęła w skorupę, wypełniła dostępną przestrzeń i zastygła. Intruzję równoległą do uwarstwienia nazywamy żyłą pokładową. Żyła przecinająca warstwy, czyli dajka, wskazuje inną drogę przemieszczania się magmy. Kontakty ze skałą otaczającą zachowują tę różnicę. Wyobraź sobie, że śledzisz ciemną granicę wzdłuż sąsiednich warstw. Jeśli cały pakiet zostanie później wygięty ku górze, intruzja może wygiąć się razem z nim. Erozja przecinająca zakrzywione ciało może odsłonić pierścieniowy ślad. Richat zawiera dwa duże ciała gabrowe o zakrzywionych obrysach na powierzchni. Gabro jest gruboziarnistą skałą magmową, powstałą podczas stygnięcia magmy pod ziemią. Wcześniejsze interpretacje traktowały te ciała jako dajki pierścieniowe związane z centralną intruzją. Późniejsze badania sprawdzały inną możliwość: starsze żyły pokładowe uniesione wraz z otaczającymi skałami osadowymi. Zmienia to kolejność wydarzeń. Badanie opublikowane w dwa tysiące dwudziestym czwartym roku dodało analizy chemiczne i badania wykorzystujące argon. Skład gabr przypomina grupy związane ze Środkowoatlantycką Prowincją Magmową, ogromnym epizodem aktywności sprzed około dwustu milionów lat. Autorzy zaproponowali początkowe wnikanie magmy równolegle do warstw. Młodsza intruzja mogła następnie podnieść starsze ciała i ich otoczenie, tworząc kopułę. Jeden wzór łączyłby odległe epizody. Dokładna geometria podziemna pozostaje przedmiotem dyskusji; ta interpretacja jest propozycją sprawdzaną na podstawie danych, a nie zdjęciem podziemia. Blisko środka różne okruchy skał są ze sobą scementowane. Co je rozbiło i co później wypełniło szczeliny?""")
put('sv-SE',4,"""En mörk, skivformad bergartskropp ligger mellan ljusa sedimentlager. Magma trängde in i jordskorpan, fyllde tillgängligt utrymme och stelnade. En intrusion som följer lagringen kallas en lagergång. En gång som skär genom lagren visar en annan väg för magman. Kontakterna bevarar skillnaden. Föreställ dig att följa den mörka gränsen längs det omgivande berget. Om hela lagerpaketet senare välvs upp kan lagergången böjas med det. Erosion genom den böjda kroppen kan blottlägga ett ringformat spår. Richat har två framträdande gabbrokroppar med böjda konturer vid ytan. Gabbro är en grovkristallin magmatisk bergart som bildas när magma svalnar under jorden. Tidigare tolkningar såg kropparna som ringgångar knutna till en central intrusion. Senare forskning undersökte en annan möjlighet: äldre lagergångar som lyftes tillsammans med de sedimentära bergarterna. Det ändrar händelsernas ordning. En studie från tvåtusentjugofyra tillförde kemiska analyser och undersökningar med argon. Gabbrons sammansättning liknar grupper kopplade till den centralatlantiska magmatiska provinsen, en enorm period av aktivitet för omkring tvåhundra miljoner år sedan. Författarna föreslog att den äldre magman först trängde in parallellt med lagren. En yngre intrusion kunde sedan lyfta de äldre kropparna och det omgivande berget till en kupol. Ett enda mönster skulle då förena avlägsna episoder. Den exakta geometrin under marken diskuteras fortfarande; lagergångstolkningen är ett förslag prövat mot data, ingen underjordisk bild. Nära mitten är bitar av olika bergarter cementerade tillsammans. Vad bröt sönder dem, och vad fyllde senare mellanrummen?""")
put('da-DK',4,"""Et mørkt, pladeformet magmatisk legeme ligger mellem lyse sedimentlag. Magma trængte ind i jordskorpen, fyldte tilgængelig plads og størknede. En intrusion parallelt med lagdelingen kaldes en laggang. En magmatisk gang, der skærer gennem lagene, viser en anden vej. Kontakterne med den omgivende bjergart bevarer forskellen. Forestil dig at følge den mørke grænse langs lagene. Hvis hele lagpakken senere hvælves op, kan laggangen bøjes med. Erosion gennem det buede legeme kan blotlægge et ringformet spor. Richat har to fremtrædende gabbrolegemer med buede omrids ved overfladen. Gabbro er en grovkornet magmatisk bjergart, dannet ved afkøling af magma under jorden. Tidligere fortolkninger beskrev legemerne som ringgange knyttet til en central intrusion. Senere undersøgelser afprøvede en anden mulighed: ældre laggange, der blev løftet sammen med de sedimentære bjergarter. Det ændrer rækkefølgen. Et studie offentliggjort i år to tusind og fireogtyve tilføjede kemiske analyser og undersøgelser med argon. Gabbroens sammensætning ligner grupper forbundet med den centralatlantiske magmatiske provins, en enorm fase af aktivitet for omkring to hundrede millioner år siden. Forfatterne foreslog, at den ældre magma først trængte ind parallelt med lagene. En yngre intrusion kunne senere løfte de gamle legemer og de omgivende lag til en kuppel. Ét mønster ville dermed samle vidt adskilte episoder. Den præcise underjordiske geometri er fortsat omdiskuteret; laggangstolkningen er et forslag afprøvet mod data, ikke et fotografi af undergrunden. Nær centrum er brudstykker af forskellige bjergarter cementeret sammen. Hvad knuste dem, og hvad fyldte senere mellemrummene?""")
put('fi-FI',4,"""Tumma, laattamainen magmakivikappale sijaitsee vaaleiden sedimenttikerrosten välissä. Magma tunkeutui maankuoreen, täytti vapaan tilan ja jähmettyi. Kerroksia myötäilevä intruusio kulkee samansuuntaisesti kerrostumisen kanssa. Kerroksia leikkaava juoni taas kertoo erilaisesta magman reitistä. Kontaktit ympäröivään kiveen säilyttävät tämän eron. Kuvittele seuraavasi tummaa rajapintaa kerrosten vierellä. Jos koko kerrospaketti myöhemmin kohoaa kaarelle, myös intruusio voi taipua. Kaarevan kappaleen läpi etenevä eroosio voi paljastaa rengasmaisen jäljen. Richatissa on kaksi huomattavaa gabrokappaletta, joiden ääriviivat kaartuvat maanpinnalla. Gabro on karkearakeinen magmakivi, joka muodostuu magman jäähtyessä maan alla. Aiemmissa tulkinnoissa kappaleet nähtiin keskiseen intruusioon liittyvinä rengasjuonina. Myöhempi tutkimus tarkasteli vaihtoehtoa: vanhempia, kerroksia myötäileviä intruusioita, jotka kohosivat sedimenttikivien mukana. Se muuttaa tapahtumien järjestystä. Vuonna kaksituhattakaksikymmentäneljä julkaistu tutkimus toi lisää kemiallisia analyysejä ja argoniin perustuvia mittauksia. Gabrojen koostumus muistuttaa Keski-Atlantin magmaattiseen provinssiin liittyviä ryhmiä. Se oli valtava magmatismin vaihe noin kaksisataa miljoonaa vuotta sitten. Kirjoittajat ehdottivat, että vanhempi magma tunkeutui aluksi kerrosten suuntaisesti. Nuorempi intruusio saattoi myöhemmin kohottaa vanhemmat kappaleet ja niitä ympäröivät kerrokset kupoliksi. Yksi pintakuvio yhdistäisi näin kaukana toisistaan olevia vaiheita. Tarkka maanalainen geometria on yhä keskustelun kohteena; tulkinta on aineistolla koeteltu ehdotus, ei valokuva maan alta. Keskuksen lähellä erilaisten kivien palaset ovat sementoituneet yhteen. Mikä rikkoi ne, ja mikä myöhemmin täytti välit?""")
put('nb-NO',4,"""Et mørkt, plateformet bergartslegeme ligger mellom lyse sedimentlag. Magma trengte inn i jordskorpen, fylte tilgjengelig plass og størknet. En intrusjon parallelt med lagdelingen kalles en laggang. En magmatisk gang som skjærer gjennom lagene, viser en annen vei. Kontaktene mot bergarten rundt bevarer forskjellen. Se for deg at du følger den mørke grensen langs lagene. Hvis hele lagpakken senere hvelves opp, kan laggangen bøyes med. Erosjon gjennom det buede legemet kan avdekke et ringformet spor. Richat har to tydelige gabbrolegemer med buede omriss ved overflaten. Gabbro er en grovkornet magmatisk bergart, dannet når magma kjøles ned under bakken. Tidligere tolkninger beskrev legemene som ringganger knyttet til en sentral intrusjon. Senere undersøkelser vurderte en annen mulighet: eldre lagganger som ble løftet sammen med sedimentbergartene. Det endrer rekkefølgen. En studie fra to tusen og tjuefire tilføyde kjemiske analyser og undersøkelser med argon. Gabbroens sammensetning ligner grupper knyttet til den sentralatlantiske magmatiske provinsen, en enorm fase av aktivitet for rundt to hundre millioner år siden. Forfatterne foreslo at den eldre magmaen først trengte inn parallelt med lagene. En yngre intrusjon kunne deretter løfte de gamle legemene og bergartene rundt til en kuppel. Ett mønster ville da samle hendelser langt fra hverandre i tid. Den nøyaktige geometrien under bakken er fortsatt omdiskutert; laggangstolkningen er et forslag prøvd mot data, ikke et fotografi av undergrunnen. Nær sentrum er biter av ulike bergarter sementert sammen. Hva knuste dem, og hva fylte senere mellomrommene?""")
put('cs-CZ',4,"""Mezi světlými sedimentárními vrstvami leží tmavé, deskovité magmatické těleso. Magma proniklo do zemské kůry, vyplnilo dostupný prostor a ztuhlo. Intruze rovnoběžná s vrstevnatostí se nazývá ložní žíla. Žíla protínající vrstvy ukazuje jinou cestu magmatu. Kontakty s okolní horninou zachovávají tento rozdíl. Představte si, že sledujete tmavou hranici podél vrstev. Pokud se celý soubor později vyklene vzhůru, může se ložní žíla ohnout společně s ním. Eroze protínající zakřivené těleso pak může odkrýt prstencovou stopu. Richat obsahuje dvě výrazná gabrová tělesa se zakřivenými obrysy na povrchu. Gabro je hrubozrnná vyvřelá hornina vzniklá ochlazováním magmatu pod zemí. Starší interpretace považovaly tato tělesa za prstencové žíly spojené s centrální intruzí. Pozdější výzkum prověřoval jinou možnost: starší ložní žíly vyzdvižené spolu s okolními sedimentárními horninami. To mění sled událostí. Studie publikovaná v roce dva tisíce dvacet čtyři přidala chemické analýzy a výzkum využívající argon. Složení gaber připomíná skupiny spojené se Středoatlantskou magmatickou provincií, obrovskou fází aktivity zhruba před dvěma sty miliony let. Autoři navrhli, že starší magma nejprve proniklo rovnoběžně s vrstvami. Mladší intruze mohla později zvednout starší tělesa i jejich okolí do klenby. Jeden povrchový obraz by tak spojoval časově vzdálené epizody. Přesná podzemní geometrie zůstává předmětem diskuse; tento výklad je návrhem ověřovaným pomocí dat, nikoli fotografií podzemí. Blízko středu jsou úlomky různých hornin stmelené dohromady. Co je rozbilo a co později vyplnilo mezery?""")

if __name__=='__main__':
    path=R/'LOCALIZATION_OVERRIDES.json'
    old=json.loads(path.read_text()) if path.exists() else {}
    for locale,sections in overrides.items():old.setdefault(locale,{}).update(sections)
    path.write_text(json.dumps(old,ensure_ascii=False,indent=2)+'\n')
    print('Reviewed complete chapter four in',len(overrides),'locales')
